global/files

组件：qian.files@2.1.1；来源：bundle / plugins/qian.bundle.base/config/qian.patch.yml。

生效配置

{
  "storage": {
    "kind": "local",
    "root": "/var/lib/qian/files",
    "endpoint": "https://platform.example.internal/files/blobs/"
  },
  "quota": {
    "perTenantBytes": 10737418240
  }
}

配置 Schema

来源：plugins/qian.files/schemas/config.schema.json。

{
  "type": "object",
  "properties": {
    "storage": {
      "type": "object",
      "required": [
        "kind"
      ],
      "properties": {
        "kind": {
          "enum": [
            "local",
            "oss",
            "s3"
          ],
          "description": "按挂载选用存储，目前支持 local。未知名称在挂载时返回 INPUT_INVALID。"
        },
        "root": {
          "type": "string",
          "description": "local 必填：对象根目录（绝对路径）。"
        },
        "bucket": {
          "type": "string"
        },
        "endpoint": {
          "type": "string",
          "description": "local 必填：宿主映射直传 / 直下端点的公开基址（绝对 http(s) 地址，路径与 MapKunFiles 的 TransferPath 一致）；oss / s3：对象存储服务端点。"
        },
        "accessKey": {
          "type": "string",
          "x-qian-sensitive": true
        },
        "secretKey": {
          "type": "string",
          "x-qian-sensitive": true
        }
      },
      "additionalProperties": false
    },
    "quota": {
      "type": "object",
      "properties": {
        "perTenantBytes": {
          "type": "integer",
          "minimum": 0,
          "description": "租户字节配额的平台默认值；租户覆盖经租户配置（ITenantSettings）写入，优先于此值。"
        }
      },
      "additionalProperties": false,
      "default": {
        "perTenantBytes": 10737418240
      }
    },
    "policies": {
      "type": "array",
      "description": "平台默认上传策略；组件也可在 Apply 中经 IFileService.Policies 登记，或在自己的 metadata/upload-policies.json 声明本组件的用途（平台宿主经 Registry 汇总，同用途以这里为准）。用途形如 \u003C组件 ID\u003E/\u003C名称\u003E，组件 ID 进入存储键。",
      "items": {
        "type": "object",
        "required": [
          "purpose",
          "allowedTypes",
          "maxSize"
        ],
        "properties": {
          "purpose": {
            "type": "string",
            "maxLength": 128,
            "pattern": "^[a-z][a-z0-9-]*(\\.[a-z][a-z0-9-]*)\u002B/[a-z][a-z0-9-]*(\\.[a-z][a-z0-9-]*)*$"
          },
          "allowedTypes": {
            "type": "array",
            "minItems": 1,
            "maxItems": 64,
            "items": {
              "type": "string"
            }
          },
          "maxSize": {
            "type": "integer",
            "minimum": 1,
            "maximum": 1099511627776
          },
          "maxCount": {
            "type": "integer",
            "minimum": 1,
            "maximum": 2147483647
          }
        },
        "additionalProperties": false
      }
    }
  },
  "additionalProperties": false,
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "required": [
    "storage"
  ]
}

