三个都是内核档的包，在 nuget.org 上。Kun.Security 提供从已认证身份读主体的 ICurrentUser，并带上了 ASP.NET Core 的 JWT 认证包。

2 写命令与判定器

把 Program.cs 整个换成：

using Kun.Authorization;
using Kun.Core.Cqrs;
using Kun.Core.Results;
using Kun.Errors.AspNetCore;
using Kun.Mediator;
using Kun.Mediator.Behaviors;
using Kun.Mediator.DependencyInjection;
using Kun.Security.DependencyInjection;

var builder = WebApplication.CreateBuilder(args);

// 认证用宿主自己的方案。这里是本机演示：令牌由 dotnet user-jwts 签发。
builder.Services.AddAuthentication().AddJwtBearer();
builder.Services.AddAuthorization();

builder.Services.AddKunErrors();
// 当前主体：从已认证的主身份读 sub、tenant_id、principal_kind（缺省按 user）。
builder.Services.AddKunSecurity();
// 权限判定器：Kun 只定义端口，判定由它回答。这里用内存里的授权表演示。
builder.Services.AddSingleton<IPermissionChecker, DemoPermissionChecker>();

builder.Services.AddKunMediator(m =>
{
    m.AddRequestHandler<ExportNotesCommand, Result<ExportResult>, ExportNotesHandler>();
    // 命令入口的执行点：在处理器之前判定，拒绝时返回 Result 失败，不抛异常。
    m.AddPermissionBehavior<ExportNotesCommand, Result<ExportResult>>(Result<ExportResult>.Fail);
});

var app = builder.Build();
app.UseKunErrors();
app.UseAuthentication();
app.UseAuthorization();

app.MapPost("/notes/export", async (ISender sender, CancellationToken ct) =>
{
    var result = await sender.Send(new ExportNotesCommand(), ct);
    return result.IsSuccess ? Results.Ok(result.Value) : KunResults.Error(result.Error);
});

app.Run();

/// <summary>导出笔记。所需权限在编译期写死，请求体改不了它。</summary>
public sealed record ExportNotesCommand : ICommand<Result<ExportResult>>, IPermissionProtectedRequest
{
    public static IReadOnlyList<string> RequiredPermissions { get; } = ["com.example.notes:note:export"];
}

public sealed record ExportResult(int Count);

public sealed class ExportNotesHandler : IRequestHandler<ExportNotesCommand, Result<ExportResult>>
{
    public ValueTask<Result<ExportResult>> Handle(ExportNotesCommand request, CancellationToken cancellationToken)
        => ValueTask.FromResult<Result<ExportResult>>(new ExportResult(3));
}

/// <summary>演示用的判定器：按主体编号查一张写死的授权表。真实系统里换成权限引擎。</summary>
public sealed class DemoPermissionChecker : IPermissionChecker
{
    private static readonly Dictionary<string, string[]> Grants = new(StringComparer.Ordinal)
    {
        ["alice"] = ["com.example.notes:note:read", "com.example.notes:note:export"],
        ["bob"] = ["com.example.notes:note:read"],
    };

    public ValueTask<PermissionDecision> CheckAsync(PermissionRequest request, CancellationToken cancellationToken = default)
    {
        var allow = request.Subject.Kind == "user"
            && Grants.TryGetValue(request.Subject.Id, out var granted) && granted.Contains(request.Permission);
        return ValueTask.FromResult(new PermissionDecision(allow, allow ? "granted" : "not_granted", allow ? ["demo"] : []));
    }

    public async ValueTask<IReadOnlyList<PermissionDecision>> BatchCheckAsync(IReadOnlyList<PermissionRequest> requests, CancellationToken cancellationToken = default)
    {
        var decisions = new List<PermissionDecision>(requests.Count);
        foreach (var request in requests)
            decisions.Add(await CheckAsync(request, cancellationToken));
        return decisions;
    }

    public ValueTask<IReadOnlyList<string>> ListPermissionsAsync(AuthorizationSubject subject, CancellationToken cancellationToken = default)
        => ValueTask.FromResult<IReadOnlyList<string>>(Grants.TryGetValue(subject.Id, out var granted) ? granted : []);

    public ValueTask<IReadOnlyList<string>> ListAllowedActionsAsync(AuthorizationSubject subject, string resourceType, string? resourceId = null, CancellationToken cancellationToken = default)
        => ValueTask.FromResult<IReadOnlyList<string>>([]);

    public ValueTask<PermissionDecision> ExplainAsync(PermissionRequest request, CancellationToken cancellationToken = default)
        => CheckAsync(request, cancellationToken);
}

命令实现 IPermissionProtectedRequest，用静态的 RequiredPermissions 声明全部所需权限，全部放行才执行处理器。

AddPermissionBehavior 把判定接在这个命令的处理器前面；拒绝时用你给的工厂（这里是 Result<ExportResult>.Fail）返回失败：未认证是 UNAUTHENTICATED（401），其余拒绝一律是 AUTHZ_DENIED（403）。

3 签本机测试令牌

dotnet user-jwts create --name alice -o token
dotnet user-jwts create --name bob -o token
dotnet user-jwts create --name carol -o token
dotnet build

每条命令打印一个令牌，sub 就是 --name 的值；把三个令牌分别记下来。dotnet user-jwts 是 .NET SDK 自带的本机开发工具：签名密钥放进你的用户机密，受众取项目 Properties/launchSettings.json 里的地址，只在 Development 环境下生效。它往项目文件里加了 UserSecretsId，所以要重新构建一次；不重新构建，令牌会因为找不到签名密钥而全部被拒。

生产里换成真实的令牌校验。平台里是网关校验外部令牌、再签发短期的服务间令牌，下游服务用 AddKunServiceAuthentication 校验，见服务间 JWT 认证（英文）。

4 跑起来

dotnet run --launch-profile http

终端会打印 Now listening on: http://localhost:<端口>，端口是建项目时随机分配的、写在 launchSettings.json 里，令牌的受众就是这个地址。另开一个终端，把地址和三个令牌放进环境变量：

BASE=http://localhost:5013
ALICE=<alice 的令牌>
BOB=<bob 的令牌>
CAROL=<carol 的令牌>

curl -s -X POST "${BASE}/notes/export" -w '\nHTTP %{http_code}\n'
curl -s -X POST "${BASE}/notes/export" -H "Authorization: Bearer ${BOB}" -w '\nHTTP %{http_code}\n'
curl -s -X POST "${BASE}/notes/export" -H "Authorization: Bearer ${ALICE}" -w '\nHTTP %{http_code}\n'

不带令牌是 401，bob 只有读权限是 403，alice 有导出权限是 200：

{"type":"https://qian.dev/problems/protocol/UNAUTHENTICATED","title":"未认证","status":401,"detail":"缺少有效凭据或令牌已失效，请重新认证。","instance":"/notes/export","code":"UNAUTHENTICATED","message":"缺少有效凭据或令牌已失效，请重新认证。","trace_id":"1bc697f1545c1b9604d230334544d66a"}

{"type":"https://qian.dev/problems/protocol/AUTHZ_DENIED","title":"无权执行","status":403,"detail":"当前主体无权执行该操作。可调用权限解释接口查看缺少的权限点。","instance":"/notes/export","code":"AUTHZ_DENIED","message":"当前主体无权执行该操作。可调用权限解释接口查看缺少的权限点。","trace_id":"2811c7a2f3b2c71476f97ad6aa7a6571"}

{"count":3}

401、403 贴的是中文界面语言下的文案；在英文等别的语言环境里启动，title、detail、message 是那种语言的，code 与状态码不变。

忘了接执行点会怎样。 把 AddPermissionBehavior 那一行删掉再请求，命令不会执行：第一次 Send 就抛出 InvalidOperationException（「受保护请求未装配权限行为：ExportNotesCommand」），响应是 500 的 INTERNAL。实现了 IPermissionProtectedRequest 的命令不会因为漏装而被放行。

5 再接 HTTP 端点

HTTP 端点的执行点 RequireKunPermission 在平台档的包 Kun.Authorization.AspNetCore 里，从 CavaiLAB 的 GitHub Packages 装，要一个带 read:packages 权限的 GitHub 令牌。

先停掉服务，在项目目录里放上发布页附带的包源映射，设好凭据再加包：

curl -fsSL -o NuGet.config https://github.com/CavaiLAB/kun/releases/download/v2026.11.24/NuGet.config
export KUN_PLATFORM_FEED_USER=<你的 GitHub 用户名>
export KUN_PLATFORM_FEED_TOKEN=<带 read:packages 权限的令牌>
dotnet add package Kun.Authorization.AspNetCore --version 2026.11.24

这份 NuGet.config 写好了两个包源与逐包的映射：内核档从 nuget.org，平台档从 GitHub Packages，凭据从上面两个环境变量读，令牌不落进文件。

在 Program.cs 里加三处：

using Kun.Authorization.AspNetCore;

// 放在登记 DemoPermissionChecker 的下一行
// HTTP 入口的执行点（平台档的包）：普通宿主用上面登记的判定器。
builder.Services.AddKunAuthorization();

// 放在 app.MapPost("/notes/export", …) 之前
app.MapGet("/notes", () => Results.Ok(new[] { "周报", "月报" }))
    .RequireKunPermission("com.example.notes:note:read");

重新构建、启动（dotnet run --launch-profile http），启动日志里有一行「授权已使用库模式，只检查 IPermissionChecker，不写决策审计、不比对身份修订。」。四种身份的结果：

调用方	GET /notes（要 read）	POST /notes/export（要 export）
不带令牌	401	401
bob（只有 read）	200	403
carol（没有授权）	403	403
alice（read 与 export）	200	200

RequireKunPermission 可以调多次，表示全部权限都要放行；权限点不是 <组件 id>:<资源>:<动作> 的全名时，映射端点时就抛 ArgumentException。

它同时给端点加上 401、403 的 ErrorDetail 响应声明，并把权限点写进 OpenAPI 的 x-qian-permission。

库模式对 agent 主体与带委托链的请求一律拒绝。

gRPC 方法

gRPC 方法上标 [RequiresPermission]，再装授权拦截器（AddKunGrpc 在内核档的 Kun.Grpc 里，AddKunAuthorizationInterceptor 在 Kun.Authorization.AspNetCore 里）：

builder.Services.AddKunGrpc(options => options.AddKunAuthorizationInterceptor());

[RequiresPermission("com.example.notes:note:read")]
public override Task<NoteReply> GetNote(NoteRequest request, ServerCallContext context) { /* … */ }

宿主启动时校验方法上的权限点，不是全名就报错；没装拦截器时，标了权限的方法一律拒绝执行。本页没有单独演示 gRPC；仓库里客户参考应用的测试覆盖了 gRPC 与 HTTP 对同一权限点判定一致、带委托链的令牌在两种入口都被拒绝。

6 平台模式：权限引擎

平台宿主不让每个服务自己写判定器，而是装权限组件 qian.authz（Kun.Authorization.Rbac）。下面是现状与入口，没有做成一步步的教程。

组件声明自己的权限点与默认角色。 组件文件夹里两份文件，以客户参考应用为例：

[
  { "resource": "customer", "actions": ["read"] },
  { "resource": "customer", "actions": ["write"] },
  { "resource": "customer", "actions": ["export"], "risk": { "export": "high" }, "stepUp": ["export"], "terminals": { "export": ["web"] } }
]

上面是 metadata/permissions.json 的写法（节选）；权限点的全名由组件 id 拼上资源与动作，如 qian.sample.crm:customer:read。也可以在 .NET 代码里用 [Permission("customer", "export", Risk = PermissionRisk.High, RequiresStepUp = true, Terminals = ["web"])] 声明（特性在平台档的 Kun.Authorization.Rbac.Abstractions 里），再由清单工具派生出这份文件。默认角色写在 metadata/roles.json：

[
  { "role": "tenant.owner", "grant": ["qian.sample.crm:customer:*"] },
  { "role": "tenant.user", "grant": ["qian.sample.crm:customer:read"] }
]

平台模式做的事。 权限点持久化成目录；租户开通时建四个内置角色（tenant.owner、tenant.admin、tenant.developer、tenant.user），按各组件的 roles.json 写默认授权；判定查真实的角色与授权，带主体快照缓存，授予或撤销后不等缓存过期；判定写决策审计（放行的判定可以按比例采样，缺省全写）；令牌带的身份修订旧了，返回 401。谁成为租户的管理员，由开通流程的初始授权决定，不从令牌里的角色推出来。

宿主怎么装。 平台模式用另一个重载登记：services.AddKunAuthorization(http => …)，回调返回当前请求可注入权限组件的插件上下文；app.UseKunAuthorization() 放在 app.UseAuthorization() 之后。身份、可信的租户边界与权限组件要先就绪。规则见 Kun.Authorization.AspNetCore 的说明与权限组件的说明。

能照着看的。 客户参考应用 samples/Kun.Sample.Crm 装的就是真实的权限组件，它的测试 tests/Kun.Sample.Crm.Tests 里的 IdentityAuthzTests 起真实的 PostgreSQL 容器，验了开通后 Owner 有读、写、导出，使用者只有读；gRPC 与 HTTP 判定一致；带委托链的令牌被拒；撤销授予后旧令牌失效。跑这组测试要 Docker，前置条件见 tests/README.md。

两个只读的 HTTP 端点（平台模式，MapKunAuthz）：GET /api/authz/me/permissions 列出当前主体在本租户持有的权限点，带风险、step-up、终端限制，界面可以据此决定显示什么，判定仍在后端入口上做；GET /api/authz/meta 发布数据权限的元数据（有哪些数据范围、过滤条件、系统变量），不返回实际的授予。

还没有的

想做的	现状
Kun 宿主以外的系统来问权限：管理端、工作区服务、页面插件、别的语言写的服务	远程的授权接口与客户端包是规划，还没有实现。要定的十个问题 2026-11-26 已定（S1-DEC-045），任务已建，都没有开始：契约定稿 S1-AZ-011，登记机器身份的入口 S1-AZ-024，端点 S1-AZ-012、S1-AZ-013、S1-AZ-020，客户端包 S1-AZ-014、S1-AZ-015。现在 HTTP 上只有上面两个只读端点
数据权限与字段权限，比如按部门、按人过滤数据	端口已有（IDataPermissionFilter、IFieldPolicy），求值没有做；平台模式下现在一律拒绝：数据过滤给恒假条件，字段一个也不给
Agent 主体与委托	没有启用：带委托链的请求在三种入口都被拒绝
角色管理接口，组织、岗位、组的继承	规划，都没有开始：角色管理接口归 S1-AZ-021，组织、岗位、组的继承归 S1-AZ-022
用 qian add authz 单独安装权限组件	没有收口（S1-RT-040）

再往后

组件怎么写、清单怎么派生：写一个组件。

权限的设计与取舍：ADR-006 鉴权模型；权限组件在组件目录里的条目：qian.authz。

判定端口与三种入口的完整规则：Kun.Authorization 的说明。

组件是 Kun 分发与安装的单位：一个文件夹，里面一份清单 .qian-plugin/plugin.json，加上声明式的内容（工具描述、权限点、角色、事件、技能等），可以带 .NET 代码，也可以一行代码都没有。租户、身份、权限这些平台能力本身也是这样的组件。概念见组件。

这一页做一个带代码的组件 com.example.notes：它提供一个笔记服务，声明一项「新建笔记」的能力；清单里能从代码推出来的字段交给清单工具派生；最后写一个小宿主把它装上。末尾另讲无代码的组件怎么起步。

下面的命令与输出在 2026-11-26 用 .NET SDK 10.0.404、Kun 2026.11.24 照着跑过一遍。

这一页让你写进文件的代码，在 Kun 仓库的 samples/docs/write-a-component 里有一份。仓库的 CI 照第 1 至 5 步做一遍：平时用当前源码打的包和当前源码构建的清单工具，每次发版用刚发布的包和发布标签，清单工具的输出与宿主的输出都要和页面上的对得上。

名字里带 qian 的地方（清单目录 .qian-plugin/、命令行 qian、平台组件 id 的前缀 qian.）是保留下来的运行期字面，不表示产品名。

先准备

照上手准备好 .NET SDK 10，能访问 nuget.org。

Git。清单工具还没有发布成包，要从 Kun 仓库的发布标签构建（第 4 步）。

1 建类库，装包

mkdir notes-demo && cd notes-demo
dotnet new classlib -n Acme.Notes
rm Acme.Notes/Class1.cs
cd Acme.Notes
dotnet add package Kun.Runtime --version 2026.11.24
dotnet add package Kun.Plugin.Sdk --version 2026.11.24
dotnet add package Kun.Plugin.Sdk.Generators --version 2026.11.24
cd ..

三个都是内核档的包，在 nuget.org 上：Kun.Runtime 是组件运行时（上下文、服务键、效果栈、装载器），Kun.Plugin.Sdk 放代码声明用的特性，Kun.Plugin.Sdk.Generators 是源生成器，dotnet add package 会把它标成只在构建时用（PrivateAssets 为 all）。

2 写入口与能力

新建 Acme.Notes/NotesPlugin.cs：

using System.Collections.Concurrent;
using System.Text.Json;
using System.Text.Json.Serialization;
using Kun.Plugin.Sdk;
using Kun.Runtime;

namespace Acme.Notes;

/// <summary>组件入口：一个组件 id 对应一个入口类。</summary>
[KunPlugin("com.example.notes")]
public sealed class NotesPlugin : IKunPlugin
{
    /// <summary>本组件提供的服务键。别的组件在自己的 Inject 里写上它，就能拿到这个服务。</summary>
    public static readonly ServiceKey Notes = new("ExampleNotes");

    /// <summary>本组件挂载前要先就绪的服务键；这个组件不依赖别人。</summary>
    public IReadOnlyList<ServiceKey> Inject => [];

    public ValueTask ApplyAsync(IPluginContext ctx, JsonElement config, CancellationToken ct)
    {
        // Provide 的登记进当前插件的效果栈，卸载时自动撤销。
        ctx.Provide(Notes, new NoteBook());
        return ValueTask.CompletedTask;
    }
}

/// <summary>本组件对外提供的服务。</summary>
public sealed class NoteBook
{
    private readonly ConcurrentDictionary<Guid, string> _notes = new();

    public Guid Add(string title)
    {
        var id = Guid.CreateVersion7();
        _notes[id] = title;
        return id;
    }

    public int Count => _notes.Count;
}

/// <summary>声明一项能力：输入、输出的 Schema 由类型派生，工具描述由清单工具写进 tools/。</summary>
[Capability("note.create", typeof(NoteCreated), typeof(NotesJson),
    Description = "为当前租户新建一条笔记；修改已有笔记请用其它能力。",
    SideEffect = "write", Idempotent = true, RequiredScopes = ["com.example.notes:write"])]
public sealed partial record CreateNote(Guid IdempotencyKey, string Title);

public sealed record NoteCreated(Guid Id, string Title);

[JsonSourceGenerationOptions(PropertyNamingPolicy = JsonKnownNamingPolicy.CamelCase,
    UnmappedMemberHandling = JsonUnmappedMemberHandling.Disallow, RespectRequiredConstructorParameters = true)]
[JsonSerializable(typeof(CreateNote))]
[JsonSerializable(typeof(NoteCreated))]
public sealed partial class NotesJson : JsonSerializerContext;

[KunPlugin("com.example.notes")] 标出组件入口。组件 id 是反向域名风格的小写名字。

Inject 列出挂载前要先就绪的服务键；ApplyAsync 里用 Provide 登记本组件提供的服务，登记进效果栈，卸载时按注册的逆序撤销。

[Capability] 标在 partial 的请求类型上：输入、输出的 JSON Schema 从源生成的 JsonTypeInfo 导出，序列化设置就是契约（上面的写法不接受多余字段、构造参数必填）；描述、副作用、幂等、所需 scope 写进工具描述。写操作缺省记审计；destructive 的策略提示缺省是要人确认。

3 手写清单

在类库旁边建组件文件夹 notes/：

mkdir -p notes/.qian-plugin notes/tools

新建 notes/.qian-plugin/plugin.json：

{
  "id": "com.example.notes",
  "version": "0.1.0",
  "description": "示例组件：提供一个笔记服务和一项新建笔记的能力。",
  "author": { "name": "Example" },
  "license": "MIT",
  "interface": { "displayName": "示例笔记", "category": "productivity" },
  "inject": [],
  "provides": [],
  "scopes": ["global", "tenant"],
  "surfaces": { "tools": "./tools" },
  "policy": { "tier": "official", "sandbox": "none", "authentication": "ON_INSTALL" }
}

这些字段是清单的必填项。能从代码推出来的（inject、provides、runtime、工具描述）先留空，下一步由工具补上；组件 id、版本、展示、策略、scope 一直是手写的。

信任等级（policy.tier）要留意：带进程内代码的组件（派生出来的 runtime.form 是 module），等级只能是 system 或 official，写成别的，清单工具的校验就不过（报 .qian-plugin/plugin.json#/runtime/form）。平台的规则是只有平台自己的和官方的组件，代码可以进平台的共享进程；别的来源的代码要隔离着跑，那条路是规划，见组件模型规格第 11 节。没有代码的组件，各个等级都可以发布。

4 用清单工具派生

先构建组件，再从 Kun 仓库的发布标签构建清单工具：

dotnet build Acme.Notes -c Release
git clone --depth 1 --branch v2026.11.24 https://github.com/CavaiLAB/kun.git kun-v2026.11.24
dotnet build kun-v2026.11.24/tools/Kun.Plugin.Tool -c Release -p:Version=2026.11.24

清单工具与组件要用同一个版本的 Kun。发布的包里程序集版本是 2026.11.24.0，从源码构建工具时用 -p:Version=2026.11.24 对上；对不上，工具加载不了组件的程序集。

先只读地比对：

TOOL=kun-v2026.11.24/tools/Kun.Plugin.Tool/bin/Release/net10.0/Kun.Plugin.Tool.dll
DLL=Acme.Notes/bin/Release/net10.0/Acme.Notes.dll
dotnet "${TOOL}" check "${DLL}" notes

退出码是 1，列出清单与代码的差异：

{"changed":[{"file":"tools/note.create.json","pointer":""},{"file":".qian-plugin/plugin.json","pointer":"/provides"},{"file":".qian-plugin/plugin.json","pointer":"/runtime"},{"file":".qian-plugin/plugin.json","pointer":"/x-qian-generated"}],"applied":false}

同步，再比对一次：

dotnet "${TOOL}" sync "${DLL}" notes
dotnet "${TOOL}" check "${DLL}" notes

sync 退出码 0；第二次 check 输出 {"changed":[],"applied":false}，退出码 0。清单里补上了这几项：

{
  "provides": ["ExampleNotes"],
  "runtime": { "form": "module", "entry": "Acme.Notes.NotesPlugin, Acme.Notes" },
  "x-qian-generated": {
    "$generated": true,
    "fields": ["/inject", "/provides", "/runtime/form", "/runtime/entry"],
    "tools": ["tools/note.create.json"],
    "metadata": {}
  }
}

notes/tools/note.create.json 是派生出来的工具描述，下面是其中一部分；完整文件还有 inputSchema、outputSchema（从 CreateNote、NoteCreated 导出）与 schemaSha256：

{
  "name": "note.create",
  "description": "为当前租户新建一条笔记；修改已有笔记请用其它能力。",
  "sideEffect": "write",
  "policyHint": "allow",
  "idempotent": true,
  "requiredScopes": ["com.example.notes:write"],
  "dataClassification": "internal",
  "audit": true,
  "agent": { "expose": false, "requiresConfirmation": false },
  "binding": { "kind": "command", "id": "com.example.notes/note.create" }
}

几条规矩：

check 只读：有差异退出 1，输入不对（比如上面的信任等级）退出 2，错误写成一行 ErrorDetail。

代码里删掉一项 [Capability]、重新构建以后，check 会报出旧的 tools/note.create.json 与 /x-qian-generated/tools，sync 时把那个文件撤下。

改了代码就重新构建、重新 sync；放进持续集成时跑 check，有差异就失败。Kun 仓库对自己的全部组件就是这样做的。

工具要加载你的程序集来读生成的元数据，只对自己信得过的本地构建用，不能拿它校验来路不明的组件包。

5 装进宿主

dotnet new console -n NotesHost
cd NotesHost
dotnet add reference ../Acme.Notes/Acme.Notes.csproj

把 NotesHost/Program.cs 换成：

using System.Text.Json;
using Acme.Notes;
using Kun.Runtime;
using Microsoft.Extensions.DependencyInjection;

// 平台宿主从清单读 provides；这里照做，读同步之后的 plugin.json。
using var manifest = JsonDocument.Parse(File.ReadAllText(args[0]));
var provides = manifest.RootElement.GetProperty("provides").EnumerateArray()
    .Select(item => new ServiceKey(item.GetString()!)).ToArray();

await using var services = new ServiceCollection().BuildServiceProvider();
await using var runtime = new PluginLoader(services);

var entry = new PluginEntry("notes", "com.example.notes", "0.1.0", ScopeKey.Global, 0, JsonDocument.Parse("{}").RootElement);
await runtime.MountAsync([new PluginDefinition(entry, new NotesPlugin(), provides)]);
Console.WriteLine($"挂载后：{runtime.GetState("notes", ScopeKey.Global)}");

var notes = runtime.GetContext("notes", ScopeKey.Global).Inject<NoteBook>(NotesPlugin.Notes);
notes.Add("周报");
Console.WriteLine($"笔记数：{notes.Count}");

await runtime.UnmountAsync("notes", ScopeKey.Global);
Console.WriteLine($"卸载后挂载树里的条目数：{runtime.DumpConfig().Count}");

dotnet run -- ../notes/.qian-plugin/plugin.json

挂载后：Ready
笔记数：1
卸载后挂载树里的条目数：0

清单里的 provides 不是摆设。装载器在调用任何 ApplyAsync 之前，按各条目的 Inject 与清单的 provides 检查依赖、排挂载顺序：另一个组件的 Inject 写了 ExampleNotes 时，清单写全了，装载器先挂 notes 再挂它；清单少了 provides，MountAsync 直接报 DEPENDENCY_MISSING（中文界面语言下的文案是「请求的服务键 ExampleNotes 无人提供」，别的语言环境下文案不同，错误码不变）。这也是改了代码要重新 sync 的原因。

平台宿主不用这样手写：它按 profile 与补丁解析出条目，从清单读入口与 provides，再交给同一个装载器，见profile 与 patch。

